F = "en"
E = ["english"]
EN = "Baloo Bhaijaan 2, sans-serif"


def ec(text, fill, size=26):
    return card(text, fill, size, font=EN, ltr=True)


def feel(mouth, extra="", fill="#FFD25A"):
    """A feeling: a round face that SHOWS it (no added face)."""
    return (f'<circle cx="50" cy="52" r="40" fill="{fill}" {{OL}}/><circle cx="36" cy="44" r="5" fill="#3b2a1a"/><circle cx="64" cy="44" r="5" fill="#3b2a1a"/>'
            f'{mouth}{extra}')


